typedef double (*FunctionPtr)(double);

double simpson_integration(FunctionPtr f, double a, double b, int N) {
    if (N <= 0 || N % 2 != 0) {
        return 0.0; // Handle invalid N (though problem states N must be even)
    }
    if (a == b) {
        return 0.0; // Integral over zero interval is zero
    }

    double h = (b - a) / N;
    double sum = f(a) + f(b); // f(x_0) + f(x_N)

    for (int i = 1; i < N; ++i) {
        double x_i = a + i * h;
        if (i % 2 == 1) {
            sum += 4.0 * f(x_i); // Odd indices: 4 * f(x_i)
        } else {
            sum += 2.0 * f(x_i); // Even indices: 2 * f(x_i)
        }
    }

    return (h / 3.0) * sum;
}

